type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();
    
    assert!(len == r || len == c, "Array length must match one dimension of shape.");
    
    let mut matrix = Vec::with_capacity(r);
    
    if len == r {
        // Broadcast along columns - a treated as column vector
        for i in 0..r {
            let value = a[i];
            let row = vec![value; c];
            matrix.push(row);
        }
    } else {
        // len == c, broadcast along rows - a treated as row vector
        for _ in 0..r {
            matrix.push(a.clone());
        }
    }
    
    matrix
}